/// <summary>
/// CB395_CSDFulfilementInterBranchTransfer.
/// Abstract class responsible for creating CSD transfer orders.
/// </summary>
abstract class METCreateCSDTransferOrder
{
    METFulfilmentProfileId    profileId;
    List                      salesLineList,
                              profileRuleList;
    Map                       transferOrderMap;
    Set                       transferIdSet;
    RecordInsertList          transferLineInsertList;
    boolean                   doSetStagingLane;
    Qty                       unitConvFactor,
                              unitConvConvertedQty,
                              unitConvStoredQty;
    int                       unitConvStoredQtyFactored;
    InventLocationId          supplyWarehouse;

    //Table variables.
    InventTransferTable       transferTable;
    METInventTransferTableExt metTransferTable;
    METInventTransferLine     metTransferLine;
    InventTransferLine        transferLine;
    SalesLine                 salesLine;
    SalesTable                salestable;
    METSalesTable             metSalesTable;
    METSalesLine              metSalesLine;
    InventLocation            toInventLocation;
    METInventLocation         metToInventLocaiton;
    METFulfilmentProfile      profile;
    METWaveTable              waveTable;
    boolean                   canContinueFromStagingLane;

}

Method.Source:
/// <summary>
/// Sets supply warehouse.
/// </summary>
protected abstract void setSupplyWarehouse()
{

}

/// <summary>
/// Gets waveTable.
/// </summary>
/// <returns>WaveTable</returns>
public METWaveTable getWaveTable()
{
    if (!waveTable)
    {   
        METWaveLine waveLine;

        select firstonly waveTable
            where waveTable.WaveStatus == METCSDWaveStatus::Open
            exists join waveLine
                where waveLine.WaveId == waveTable.WaveId
                &&  waveLine.DocumentNumber == salestable.SalesId
                &&  waveLine.Type == METType::SalesOrder;
    }

    return waveTable;
}

/// <summary>
/// Initializes class variables.
/// </summary>
protected void init()
{
    transferIdSet           = new Set(Types::String);
    transferOrderMap        = new Map(Types::Record, Types::Class);
    transferLineInsertList  = new RecordInsertList(tableNum(InventTransferLine));
    profile                 = METFulfilmentProfile::find(profileId);
    toInventLocation        = InventLocation::find(profile.InventLocationId);
    metToInventLocaiton     = toInventLocation.metInventLocation();

    this.initProfileRuleList();
    this.initStagingLaneSetup();
}

/// <summary>
/// Initialzes list that will contain rule for the profile.
/// </summary>
private void initProfileRuleList()
{
    METFulfilmentRule rule;

    profileRuleList = new List(Types::Record);

    Info(strFmt("@MET:ProfileRuleTO", profileId));

    while select rule
            order by rule.Sequence asc
        where rule.ProfileId == profileId
        &&    rule.Type != METFulfilmentRuleType::TOCreation
    {
        profileRuleList.addEnd(rule);
    }
}

/// <summary>
/// Initialize staging lane setup.
/// </summary>
private void initStagingLaneSetup()
{
    if (toInventLocation.METCustStartingPosition > 0)
    {
        doSetStagingLane = true;
    }
}

/// <summary>
/// Applies rules for profile.
/// </summary>
protected void applyRules()
{
    ListEnumerator enum;

    enum = profileRuleList.getEnumerator() as ListEnumerator;

    while (enum && enum.moveNext())
    {
        METFulfilmentRule rule = enum.current();

        switch (rule.Type)
        {
            case METFulfilmentRuleType::UOMConversion:
                this.applyUOMConversionRule(rule.Apply);
                break;

            case METFulfilmentRuleType::Substitutes:
                this.applySubstitutesRule(rule.Apply);
                break;

            case METFulfilmentRuleType::CSDTOType:
                this.applyCSDTOTypeRule(rule.Apply, rule.Value);
                break;

            case METFulfilmentRuleType::Route:
                this.applyRouteRule(rule.Apply);
                break;

            case METFulfilmentRuleType::Customer:
                this.applyCustomerRule(rule.Apply);
                break;

            case METFulfilmentRuleType::OrderType:
                this.applyOrderTypeRule(rule.Apply, rule.Value);
                break;
        }
    }

    transferTable.metPackMETInventTransferTableExt(metTransferTable);
    transferLine.metPackMETInventTransferLine(metTransferLine, true);
}

/// <summary>
/// Applies UOM conversion rule.
/// </summary>
/// <param name = "_apply">Rule to apply.</param>
protected void applyUOMConversionRule(METFulfilmentRuleApply _apply)
{
    Qty qty;

    if (_apply == METFulfilmentRuleApply::SalesUnitToEA)
    {
        if (salesLine.SalesUnit != METConstants::unitEach)
        {
            qty = EcoResProductUnitConverter::convertForReleasedProduct(salesLine.ItemId,
                                                                        salesLine.inventDimId,
                                                                        transferLine.QtyTransfer,
                                                                        UnitOfMeasure::unitOfMeasureIdBySymbol(salesLine.SalesUnit),
                                                                        UnitOfMeasure::unitOfMeasureIdBySymbol(METConstants::unitEach));
            this.setTransferLineQty(qty);
            transferLine.UnitId = METConstants::unitEach;
        }
    }
    else if (_apply == METFulfilmentRuleApply::EAToSalesUnit)
    {
        if (salesLine.SalesUnit == METConstants::unitEach)
        {
            SalesUnit unit;
            InventDim inventDim;

            inventDim.InventSiteId = InventLocation::find(metSalesLine.SupplyingWarehouse).InventSiteId;
            inventDim = InventDim::findDim(inventDim);

            unit = InventItemSalesSetup::find(salesLine.ItemId, inventDim.InventDimId).METSalesUnit;

            if (!unit)
            {
                return;
            }

            unitConvFactor = EcoResProductUnitConverter::convertForReleasedProduct(salesLine.ItemId,
                                                                                   salesLine.inventDimId,
                                                                                   1,
                                                                                   UnitOfMeasure::unitOfMeasureIdBySymbol(unit),
                                                                                   UnitOfMeasure::unitOfMeasureIdBySymbol(METConstants::unitEach));

            unitConvStoredQty = transferLine.QtyTransfer;
            //real to int here is intentional as it requires whole number.
            unitConvStoredQtyFactored = real2Int(unitConvStoredQty / unitConvFactor);
            unitConvConvertedQty = unitConvFactor * unitConvStoredQtyFactored;

            this.setTransferLineQty(unitConvConvertedQty);
        }
    }

}

/// <summary>
/// Applies substitution rule.
/// </summary>
/// <param name = "_apply">Rule to apply.</param>
protected void applySubstitutesRule(METFulfilmentRuleApply _apply)
{
    if (_apply == METFulfilmentRuleApply::NotAllowSubstitutes)
    {
        metTransferLine.AllowSubstitution = NoYes::No;
    }
    else if (_apply == METFulfilmentRuleApply::CopyFromSOTypes)
    {
        METSalesOrderTypes orderType = salestable.METSalesOrderTypes();

        metTransferLine.AllowSubstitution = orderType.SubstitutesAllowed;
    }
}

/// <summary>
/// Applies CSD transfer order type rule.
/// </summary>
/// <param name = "_apply">Rule to apply.</param>
/// <param name = "_value">Value to set.</param>
protected void applyCSDTOTypeRule(METFulfilmentRuleApply _apply, METFulfilmentRuleValue _value)
{
    if (_apply == METFulfilmentRuleApply::SetValue && _value)
    {
        METCSDTOType csdTOType;

        metTransferTable.CSDTOType = str2Enum(csdTOType, _value);
    }
}

/// <summary>
/// Applies route rule.
/// </summary>
/// <param name = "_apply">Rule to apply.</param>
protected void applyRouteRule(METFulfilmentRuleApply _apply)
{
    if (_apply == METFulfilmentRuleApply::InternalTORoute)
    {
        if (metTransferTable.InternalCustomer)
        {
            METInternalTORouteLine toRouteLine;
            METRouteTable          routeTable;
            METRouteStopTable      routeStopTable;

            int weekDay = dayOfWk(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
            weekDay = weekDay mod 7;

            toRouteLine = METInternalTORouteLine::find(metTransferTable.InternalCustomer,
                                                       transferTable.InventLocationIdFrom,
                                                       weekDay);

            int weekdayOrig = weekDay;
            weekDay++; // As MetInternalTORouteLine stores week day as 0-6, we need to increase it by 1 to compare with RouteTable which stores week day as integer starting from 1 for Sunday. 1-7 represents Sunday-Saturday.
            if (toRouteLine)
            {
                metTransferTable.Route = toRouteLine.Route;
                metTransferTable.RouteStopNum = toRouteLine.RouteStopNum;
                metTransferTable.StagingLane = toRouteLine.StagingLane;
                metTransferTable.Door = toRouteLine.Door;

                select firstonly RouteIdentifier from routeTable
                        order by routeTable.RecId desc
                    where routeTable.RouteId == toRouteLine.Route
                    &&    (routeTable.DispatchDay == weekDay ||
                          routeTable.DispatchDay == weekdayOrig); //Incase of timezone difference, the route might dispatch on previous day for some users, so considering both current day and previous day for route matching.

                if (routeTable.RecId == 0)
                {
                    warning(strFmt("@MET:NoRouteStopIdentifier", transferTable.TransferId, metTransferTable.InternalCustomer, transferTable.InventLocationIdFrom, weekdayOrig));
                }
                else
                {
                    metTransferTable.RouteIdentifier = routeTable.RouteIdentifier;
                }

                select firstonly RouteStopIdentifier from routeStopTable
                        order by routeStopTable.RecId desc
                    where routeStopTable.RouteStopId == toRouteLine.RouteStopNum
                    &&    routeStopTable.RouteId == routeTable.RouteIdentifier;

                if (routeStopTable.RecId == 0)
                {
                    warning(strFmt("@MET:NoRouteStopIdentifiercheck", transferTable.TransferId, metTransferTable.InternalCustomer, transferTable.InventLocationIdFrom, weekdayOrig));
                }
                else
                {
                    metTransferTable.RouteStopIdentifier = routeStopTable.RouteStopIdentifier;
                }
            }
            else
            {
                warning(strFmt("@MET:InternalCustomerNotFound", metTransferTable.InternalCustomer, transferTable.InventLocationIdFrom, weekdayOrig));
            }
        }
        else
        {
            warning(strFmt(strFmt("@MET:InternalCustNotFound", transferTable.TransferId)));
        }
    }
}

/// <summary>
/// Applies customer rule.
/// </summary>
/// <param name = "_apply">Rule to apply.</param>
protected void applyCustomerRule(METFulfilmentRuleApply _apply)
{
    if (_apply == METFulfilmentRuleApply::CSDInternalCustomer)
    {
        if (metTransferLine.OSCCode)
        {
            METOSCCode oscCode;
            DirPartyName custName;

            waveTable = this.getWaveTable();

            oscCode = metTransferLine.OSCCode;

            switch (metTransferTable.CSDTOType)
            {
                case METCSDTOType::FullCaseGrid:

                    if (oscCode == METConstants::PPerishableOSCC)
                    {
                        custName = strFmt(METConstants::CustNameFormat1,
                                          METConstants::CSDCustName,
                                          METConstants::PerishCustName,
                                          METConstants::RunCustName,
                                          waveTable.WaveNumber,
                                          METConstants::CaseCustName);
                    }
                    else
                    {
                        custName = strFmt(METConstants::CustNameFormat2,
                                          METConstants::CSDCustName,
                                          METConstants::WaveCustName,
                                          waveTable.WaveNumber,
                                          METConstants::FullCustName);
                    }
                    break;

                case METCSDTOType::FullCaseBelt:

                    if (oscCode != METConstants::PPerishableOSCC)
                    {
                        custName = strFmt(METConstants::CustNameFormat1,
                                          METConstants::CSDCustName,
                                          METConstants::WaveCustName,
                                          waveTable.WaveNumber,
                                          METConstants::P2LCustName,
                                          METConstants::CaseCustName);
                    }
                    break;

                case METCSDTOType::SplitCaseBelt:

                    if (oscCode == METConstants::PPerishableOSCC)
                    {
                        custName = strFmt(METConstants::CustNameFormat1,
                                          METConstants::CSDCustName,
                                          METConstants::PerishCustName,
                                          METConstants::RunCustName,
                                          waveTable.WaveNumber,
                                          METConstants::PartCustName);
                    }
                    else
                    {
                        custName = strFmt(METConstants::CustNameFormat2,
                                          METConstants::CSDCustName,
                                          METConstants::WaveCustName,
                                          waveTable.WaveNumber,
                                          METConstants::SplitCustName);
                    }
                    break;

                case METCSDTOType::Inners:

                    if (oscCode == METConstants::PPerishableOSCC)
                    {
                        custName = strFmt(METConstants::CustNameFormat3,
                                          METConstants::CSDCustName,
                                          METConstants::ReplenishCustName,
                                          METConstants::PerishCustName);
                    }
                    else
                    {
                        custName = strFmt(METConstants::CustNameFormat2,
                                          METConstants::CSDCustName,
                                          METConstants::WaveCustName,
                                          waveTable.WaveNumber,
                                          METConstants::UnitCustName);
                    }
                    break;
            }

            Info(strFmt("@MET:CustNameOsccCode", oscCode, custName));

            if (custName)
            {
                CustTable custTable;
                DirPartyTable dirPartyTable;

                select firstonly AccountNum from custTable
                    where custTable.InventLocation == transferTable.InventLocationIdFrom
                    exists join dirPartyTable
                        where dirPartyTable.RecId == custTable.Party
                        &&    DirPartyTable.Name like custName;

                metTransferTable.InternalCustomer = custTable.AccountNum;
            }
        }
        else
        {
            warning(strFmt("@MET:OSCCodeNotAvailable", transferTable.TransferId, metTransferLine.inventTransferLine().ItemId));
        }
    }
}

/// <summary>
/// Applies order type rule.
/// </summary>
/// <param name = "_apply">Rule to apply.</param>
/// <param name = "_value">Value to set.</param>
protected void applyOrderTypeRule(METFulfilmentRuleApply _apply,  METFulfilmentRuleValue _value)
{
    if (_apply == METFulfilmentRuleApply::DallasOrderType && _value)
    {
        metTransferTable.WMSOrderType = _value;
    }
}

/// <summary>
/// Initializes records for creation.
/// </summary>
protected void initRecords()
{
    ListEnumerator enumerator;

    enumerator = salesLineList.getEnumerator() as ListEnumerator;

    while (enumerator && enumerator.moveNext())
    {
        InventTransIdBase salesLineInventTransId = enumerator.current();

        salesLine     = SalesLine::findInventTransId(salesLineInventTransId);
        salestable    = salesLine.salesTable();
        metSalesLine  = salesLine.metSalesLine();
        metSalesTable = salestable.metSalesTable();
        waveTable     = this.getWaveTable();

        this.setSupplyWarehouse();
        this.initTransferOrder();
    }
}

/// <summary>
/// Initializes transfer table.
/// </summary>
protected void initTransferTable()
{
    /*Note will set on insert list on header and lines.*/
    //transferTable.TransferId = InventTransferTable::numberSeq().num();
    transferTable.clear();
    transferTable.initValue();
    transferTable.InventLocationIdFrom = supplyWarehouse;
    transferTable.InventLocationIdTo = salestable.InventLocationId;
    transferTable.ShipDate = metSalesTable.SecondShipDate;
    transferTable.ReceiveDate = salestable.ShippingDateConfirmed;
    transferTable.AutoReservation = NoYes::No;

    metTransferTable.clear();
    metTransferTable.WMSOrderType = metSalesTable.WMSOrderType;
    metTransferTable.DeliveryInstructions = metSalesTable.DeliveryInstructions;
    metTransferTable.UnderBond = NoYes::No;
    metTransferTable.TransferType = METCrossDockTransferType::CSD;
    metTransferTable.OrderSplitGroup = metSalesTable.OrderSplitGroup;

    transferTable.initFromAddress();
    transferTable.initToAddress();
    transferTable.defaultField(fieldNum(InventTransferTable, InventLocationIdTransit));

    transferTable.metPackMETInventTransferTableExt(metTransferTable);
}

/// <summary>
/// Initializes transfer line.
/// </summary>
protected void initTransferLine()
{
    InventDim inventDim, inventDimTo;

    transferLine.clear();
    transferLine.initValue();
    transferLine.initFromInventTransferTable(transferTable, true);
    transferLine.initFromSalesLine(salesLine);
    //CB679 - Event order and Backorder processes for NDC & CSD - start
    this.setTransferLineQty(this.getSalesLineQty(salesLine));
    //CB679 - Event order and Backorder processes for NDC & CSD - end

    inventDim = InventDim::find(transferLine.InventDimId);

    inventDim.InventLocationId = transferTable.InventLocationIdFrom;
    inventDim.InventSiteId = InventLocation::find(inventDim.InventLocationId).InventSiteId;
    transferLine.InventDimId = InventDim::findOrCreate(inventDim).InventDimId;
    transferLine.AutoReservation = NoYes::No;

    inventDimTo.InventLocationId = transferTable.InventLocationIdTo;
    inventDimTo.InventSiteId = InventLocation::find(inventDimTo.InventLocationId).InventSiteId;
    inventDimTo = InventDim::findOrCreate(inventDimTo);

    metTransferLine.clear();
    metTransferLine.WarehouseCategory = salesLine.displayMETFilterCodeOne();
    metTransferLine.OSCCode = salesLine.displayMETOSCCode();
    metTransferLine.WarehouseUnitId = METInventLocation::getWarehouseUnit(transferLine.itemId, inventDimTo);
    metTransferLine.setCaseQtyFields();

    transferLine.metPackMETInventTransferLine(metTransferLine, true);
}

/// <summary>
/// Initializes transfer order records.
/// </summary>
protected void initTransferOrder()
{
    this.initTransferTable();
    this.initTransferLine();
}

/// <summary>
/// Creates CSD wave.
/// </summary>
protected void createCSDWave()
{
    METWaveTable waveTableLocal;

    if (!toInventLocation.METWaveRequired || !transferIdSet.elements())
    {
        return;
    }

    waveTableLocal = this.getWaveTable();

    if (waveTableLocal)
    {
        this.createTransferOrderWaveLines(waveTableLocal);
    }

}

/// <summary>
/// Creates transfer orders wavelines.
/// </summary>
/// <param name = "_WaveTable">WaveTable record.</param>
private void createTransferOrderWaveLines(METWaveTable _WaveTable)
{
    InventTransferLine   transferLineLocal;
    METWaveLine          waveLine;
    SysDaQueryExpression whereQueryExp;

    var transferLineQueryObject = new SysDaQueryObject(transferLineLocal);
    var insertObject = new SysDaInsertObject(waveLine);

    whereQueryExp = this.getTransferLineExpression(transferLineLocal);

    transferLineQueryObject.whereClause(whereQueryExp);

    transferLineQueryObject.projection().add(fieldStr(InventTransferLine, TransferId))
                                        .addValue(_waveTable.WaveId)
                                        .addValue(METType::TransferOrder)
                                        .add(fieldStr(InventTransferLine, RecId))
                                        .addValue(_waveTable.OrderExtractDateTime)
                                        .add(fieldstr(InventTransferLine, LineNum));

    insertObject.fields().add(fieldStr(METWaveLine, DocumentNumber))
                         .add(fieldStr(METWaveLine, WaveId))
                         .add(fieldStr(METWaveLine, Type))
                         .add(fieldStr(METWaveLine, DocNumRefRecId))
                         .add(fieldStr(METWaveLine, OrderExtractDateTime))
                         .add(fieldStr(METWaveLine, LineNumber));

    insertObject.query(transferLineQueryObject);

    SysDaInsertStatement insertStatement = new SysDaInsertStatement();

    ttsbegin;
    insertStatement.insert(insertObject);
    ttscommit;

}

/// <summary>
/// Gets transfer line expression.
/// </summary>
/// <param name = "_transferLine">Transfer line.</param>
/// <returns>
/// <c>SysDaQueryExpression</c>.
/// </returns>
protected SysDaQueryExpression getTransferLineExpression(InventTransferLine _transferLine)
{
    SysDaQueryExpression transferLinExpression;

    var setEnum = transferIdSet.getEnumerator() as SetEnumerator;

    while (setEnum && setEnum.moveNext())
    {
        InventTransferId transferId = setEnum.current();
        SysDaQueryExpression transferIdExp = new SysDaEqualsExpression(
                                                    new SysDaFieldExpression(_transferLine, fieldStr(InventTransferLine, TransferId)),
                                                    new SysDaValueExpression(transferId));

        if (!transferLinExpression)
        {
            transferLinExpression = transferIdExp;
        }
        else
        {
            transferLinExpression = transferLinExpression.or(transferIdExp);
        }
    }

    return transferLinExpression;
}

/// <summary>
/// Starts the process for CSD transfer orders creation.
/// </summary>
public void create()
{
    #OCCRetryCount

    try
    {
        ttsbegin;

        this.initRecords();

        //Bug 405875: UAT - CSD Perishables TO's not created on Extraction - Start.
        this.insertTransferOrderRecords();
        //Bug 405875: UAT - CSD Perishables TO's not created on Extraction - End.

        this.createCSDWave();
        this.updateTMSCarries();
        this.postCreate();

        ttscommit;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch (Exception::Deadlock)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::Deadlock;
        }
    }
    catch
    {
        throw Exception::Error;
    }

}

/// <summary>
/// Post create method as an extension point.
/// </summary>
protected void postCreate()
{
    if (doSetStagingLane)
    {
        this.updateStagingLane();
    }
}

/// <summary>
/// Bug 405875: UAT - CSD Perishables TO's not created on Extraction.
/// Fixed the issue of RecordInsertList for <c>InventTransferTable</c>.
/// Inserts transfer order records in database.
/// </summary>
private void insertTransferOrderRecords()
{
    MapEnumerator mapEnum;

    mapEnum = transferOrderMap.getEnumerator() as MapEnumerator;

    while (mapEnum && mapEnum.moveNext())
    {
        SetEnumerator       setEnum;
        Set                 transferLineSet;
        InventTransferTable transferTableLocal;
        InventTransferLine  transferLineLocal;

        transferTableLocal.clear();

        transferTableLocal = mapEnum.currentKey();

        transferTableLocal.TransferId =  InventTransferTable::numberSeq().num();

        transferTableLocal.insert();

        transferLineSet  = mapEnum.currentValue();
        setEnum = transferLineSet.getEnumerator() as SetEnumerator;

        while (setEnum && setEnum.moveNext())
        {
            transferLineLocal = setEnum.current();
            transferLineLocal.TransferId = transferTableLocal.TransferId;

            transferLineInsertList.add(transferLineLocal);
        }

        //Transfer order set is needed for CSD wavelines creation.
        transferIdSet.add(transferTableLocal.TransferId);
    }

    transferLineInsertList.insertDatabase();
}

/// <summary>
/// Adds transfer order records to map.
/// </summary>
protected final void addToTransferOrderMap()
{
    Set transferLineSet;

    //CB679 - Event order and Backorder processes for NDC & CSD - start
    if (transferLine.QtyTransfer <= 0)
    {
        return;
    }
    //CB679 - Event order and Backorder processes for NDC & CSD - end

    if (!transferOrderMap.exists(transferTable))
    {
        transferLineSet = new Set(Types::Record);
    }
    else
    {
        transferLineSet = transferOrderMap.lookup(transferTable);
    }

    transferLineSet.add(transferLine);
    transferOrderMap.insert(transferTable, transferLineSet);
}

/// <summary>
/// Gets and sets profile Id.
/// </summary>
/// <param name = "_profileId">Profile Id.</param>
/// <returns>Profile Id.</returns>
public METFulfilmentProfileId parmProfileId(METFulfilmentProfileId _profileId = profileId)
{
    profileId = _profileId;
    return profileId;
}

/// <summary>
/// Gets and sets SalesLine list.
/// </summary>
/// <param name = "_salesLineList">SalesLine list.</param>
/// <returns>SalesLine list.</returns>
public List parmSalesLineList(List _salesLineList = salesLineList)
{
    salesLineList = _salesLineList;
    return salesLineList;
}

/// <summary>
/// Constructs an object on the basis of rules defined in fulfilment profile.
/// </summary>
/// <param name = "_profileId">Profile Id.</param>
/// <param name = "_salesLineList">Salesline list.</param>
/// <param name = "_canContinueFromStagingLane">Boolan value to determine if the staging lane must continue from last staging lane or from Warehouse's customer starting position.</param>
/// <returns>
/// Objects of type <c>METCreateCSDTransferOrder</c>.
/// </returns>
public static METCreateCSDTransferOrder construct(METFulfilmentProfileId _profileId, List _salesLineList, boolean _canContinueFromStagingLane)
{
    METCreateCSDTransferOrder createCSDTransferOrder;
    METFulfilmentRule rule;

    rule = METFulfilmentRule::find(_profileId, METFulfilmentRuleType::TOCreation);

    switch (rule.Apply)
    {
        case METFulfilmentRuleApply::TOSOOneToOne:
            createCSDTransferOrder = new METCreateCSDTransferOrder_TOSOOneToOne();
            break;

        case METFulfilmentRuleApply::BulkTransferForSO:
            createCSDTransferOrder = new METCreateCSDTransferOrder_BulkTransferForSO();
            break;

        case METFulfilmentRuleApply::BulkTransferToSupplyWarehouse:
            createCSDTransferOrder = new METCreateCSDTransferOrder_BulkTransferToSupplyWarehouse();
            break;

        default:
            throw error(error::wrongUseOfFunction(funcName()));
    }

    createCSDTransferOrder.parmProfileId(_profileId);
    createCSDTransferOrder.parmSalesLineList(_salesLineList);
    createCSDTransferOrder.parmContinueFromStagingLane(_canContinueFromStagingLane);
    createCSDTransferOrder.init();

    return createCSDTransferOrder;
}

/// <summary>
/// Updates staging lane.
/// </summary>
protected void updateStagingLane()
{
}

/// <summary>
/// Updates TMS carrier.
/// </summary>
protected void updateTMSCarries()
{
    METSalesTable             metSalesTableLocal;
    SalesTable                salesTableLocal;
    TMSInventTransferTable    tmsTransferTable;
    InventTransferTable       transferTableLocal;
    METInventTransferTableExt transferTableExtLocal;

    var setEnum = transferIdSet.getEnumerator() as SetEnumerator;

    while (setEnum && setEnum.moveNext())
    {
        InventTransferId transferIdVal = setEnum.current();

        insert_recordset tmsTransferTable(CarrierCode, CarrierServiceCode, TransferId)
            select SecondaryCarrierCode, SecondaryCarrierServiceCode, transferIdVal from metSalesTableLocal
                join salesTableLocal
                    where salesTableLocal.RecId == metSalesTableLocal.SalesTable
                join transferTableExtLocal
                    where transferTableExtLocal.SalesId == salesTableLocal.SalesId
                join transferTableLocal
                    where transferTableLocal.RecId == transferTableExtLocal.InventTransferTable
                    &&    transferTableLocal.TransferId == transferIdVal;

    }
}

/// <summary>
/// Sets transfer line qty.
/// </summary>
/// <param name = "_qty">Qty to set.</param>
protected void setTransferLineQty(InventQty _qty)
{
    transferLine.QtyTransfer = _qty;
    transferLine.QtyRemainReceive = _qty;
    transferLine.QtyRemainShip = _qty;
}

/// <summary>
/// CB679 - Event order and Backorder processes for NDC & CSD
/// Gets qty from salesLine.
/// </summary>
/// <param name = "_salesLine">
/// SalesLine.
/// </param>
protected SalesQty getSalesLineQty(SalesLine _salesLine)
{

    SalesQty pickedOrDeliveredQty = this.getSalesLineConvertedQuantity(_salesLine, _salesLine.mcrPickedLineQuantity());

    if (pickedOrDeliveredQty <= 0.00)
    {
        pickedOrDeliveredQty = this.getSalesLineConvertedQuantity(_salesLine, _salesLine.mcrSalesQtyDelivered());
    }

    SalesQty qty = _salesLine.SalesQty - pickedOrDeliveredQty;

    return qty;
}

/// <summary>
/// Gets sales line picked Qty.
/// </summary>
/// <param name = "_salesLine">Sales</param>
private SalesQty getSalesLineConvertedQuantity(SalesLine _salesLine, SalesQty _qty)
{
    InventTable inventTable = _salesLine.inventTable();
    SalesQty qty =  EcoResProductUnitConverter::convertGivenUnitSymbolsForReleasedProduct(_salesLine.ItemId,
                                                                                          _salesLine.InventDimId,
                                                                                          _qty,
                                                                                          inventTable.inventUnitId(),
                                                                                          _salesLine.SalesUnit,
                                                                                          NoYes::Yes);

    return abs(qty);
}

/// <summary>
/// Method to create staging lane position counter record.
/// </summary>
/// <param name = "_inventLocation">InventLocation table buffer</param>
public void createMETStagingLanePositionCounter(InventLocation _inventLocation)
{
    METStagingLanePositionCounter stagingLanePositionCounter;
    stagingLanePositionCounter.InventLocationId = _inventLocation.InventLocationId;
    stagingLanePositionCounter.NextStagingLane = _inventLocation.METCustStartingPosition;
    stagingLanePositionCounter.insert();
}

/// <summary>
/// Parm method to get/set can continue from staging lane flag, which indicates whether to consider conitinus use of customer staging position fetched from Warehouse.
/// </summary>
/// <param name = "_canContinueFromStagingLane">Boolean value</param>
/// <returns>Boolean true represents continuous use of staging lane, false to use exiting value from Warehouse's Customer starting position</returns>
public boolean parmContinueFromStagingLane(boolean _canContinueFromStagingLane = canContinueFromStagingLane)
{
    canContinueFromStagingLane = _canContinueFromStagingLane;
    return canContinueFromStagingLane;
}
